using System;
using System.Globalization;
using System.Text.RegularExpressions;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
public class CPHInline {
 const string Key="portable.video.state", Base="http://127.0.0.1:7474";
 const string DefaultsJson=@"{""schemaVersion"":2,""library"":{},""presentation"":{""anchor"":""center"",""offsetXPercent"":0,""offsetYPercent"":0,""widthPercent"":50,""aspectRatio"":""16:9"",""fit"":""contain"",""volumePercent"":100,""titlePosition"":""bottom"",""titleSize"":24,""titleColour"":""#f8fbff"",""titleBackground"":""#000000"",""titleOpacityPercent"":68}}";
 public bool Execute(){try{string m=A("videoMode").ToLowerInvariant();if(m=="initialize")return InitializeState();if(m=="health")return Health();if(m=="configure")return Configure();if(m=="play")return Play();if(m=="stop")return Stop();throw new Exception("Unknown video mode: "+m);}catch(Exception e){CPH.LogError("[video] "+e.Message);return true;}}
 JObject Defaults(){return JObject.Parse(DefaultsJson);} JObject Payload(){try{return (JObject)JObject.Parse(Read())["payload"]??new JObject();}catch{return new JObject();}}
 bool InitializeState(){JObject old=Payload(),cfg=old["config"] as JObject;cfg=Normalize(cfg??new JObject());return Write(State(cfg,old["current"]??Hidden()));}
 bool Health(){JObject p=Payload(),c=p["config"] as JObject??Normalize(new JObject());CPH.LogInfo("[video] Health OK: schema=2 module=2.1.1 videos="+((JObject)c["library"]).Count+" visible="+((bool?)p["current"]?["visible"]??false));return true;}
 bool Configure(){string raw=A("config");if(String.IsNullOrWhiteSpace(raw))throw new Exception("Video config is required.");JObject p=Payload();return Write(State(Normalize(JObject.Parse(raw)),p["current"]??Hidden()));}
 JObject Normalize(JObject input){JObject d=Defaults(),lib=new JObject(),given=input["library"] as JObject??input["videos"] as JObject??new JObject();foreach(JProperty prop in given.Properties()){JObject i=prop.Value as JObject;if(i==null)continue;string id=Id((string)i["id"]??prop.Name),src=((string)i["src"]??"").Trim();if(id==""||!Safe(src))continue;lib[id]=new JObject{{"id",id},{"label",Limit((string)i["label"]??id,80)},{"src",src},{"enabled",(bool?)i["enabled"]??true}};}if(lib.Count==0)lib=(JObject)d["library"].DeepClone();JObject dp=(JObject)d["presentation"],p=input["presentation"] as JObject??new JObject();return new JObject{{"schemaVersion",2},{"library",lib},{"presentation",new JObject{{"anchor",Choice((string)p["anchor"],new[]{"top-left","top","top-right","left","center","right","bottom-left","bottom","bottom-right"},(string)dp["anchor"])},{"offsetXPercent",Clamp((double?)p["offsetXPercent"]??(double)dp["offsetXPercent"],-50,50)},{"offsetYPercent",Clamp((double?)p["offsetYPercent"]??(double)dp["offsetYPercent"],-50,50)},{"widthPercent",Clamp((double?)p["widthPercent"]??(double)dp["widthPercent"],10,100)},{"aspectRatio",Choice((string)p["aspectRatio"],new[]{"16:9","4:3","1:1","source"},(string)dp["aspectRatio"])},{"fit",Choice((string)p["fit"],new[]{"contain","cover","fill"},(string)dp["fit"])},{"volumePercent",Clamp((double?)p["volumePercent"]??(double)dp["volumePercent"],0,100)},{"titlePosition",Choice((string)p["titlePosition"],new[]{"top","bottom"},(string)dp["titlePosition"])},{"titleSize",Clamp((double?)p["titleSize"]??(double)dp["titleSize"],12,72)},{"titleColour",Colour((string)p["titleColour"],(string)dp["titleColour"])},{"titleBackground",Colour((string)p["titleBackground"],(string)dp["titleBackground"])},{"titleOpacityPercent",Clamp((double?)p["titleOpacityPercent"]??(double)dp["titleOpacityPercent"],0,100)}}}};}
 bool Play(){JObject p=Payload(),cfg=p["config"] as JObject??Normalize(new JObject());string id=Id(A("id"));if(id=="")id="40today";JObject item=cfg["library"]?[id] as JObject;string src=A("src");if(src==""&&item!=null&&((bool?)item["enabled"]??true))src=(string)item["src"];if(src==""||!Safe(src))throw new Exception("Unknown, disabled, or unsafe video: "+id);JObject pr=cfg["presentation"] as JObject;long now=Now();string fit=A("fit"),vol=A("volume");JObject cur=new JObject{{"visible",true},{"id",id},{"src",Absolute(src)},{"title",Limit(A("title"),140)},{"fit",fit==""?(string)pr["fit"]:Choice(fit,new[]{"contain","cover","fill"},"contain")},{"volume",vol==""?(double)pr["volumePercent"]/100.0:Number("volume",1,0,1)},{"muted",Bool("muted",false)},{"loop",Bool("loop",false)},{"presentation",pr.DeepClone()},{"startedAtMs",now},{"lastStartAtMs",now},{"hideAtMs",JValue.CreateNull()},{"lastError",""}};foreach(string k in new[]{"x","y","width","height"}){int v;if(Int32.TryParse(A(k),out v))cur[k]=v;}return Write(State(cfg,cur));}
 bool Stop(){JObject p=Payload();long expected;if(Int64.TryParse(A("startedAtMs"),out expected)&&expected>0){long active=(long?)p["current"]?["startedAtMs"]??0;if(active>0&&active!=expected)return true;}return Write(State(p["config"] as JObject??Normalize(new JObject()),Hidden()));}
 JObject State(JObject c,JToken current){return new JObject{{"moduleVersion","2.0.0"},{"serverTimeMs",Now()},{"config",c},{"current",current}};} JObject Hidden(){return new JObject{{"visible",false},{"startedAtMs",JValue.CreateNull()},{"hideAtMs",JValue.CreateNull()},{"lastError",A("error")}};}
 bool Write(JObject p){long r=1;try{r=((long?)JObject.Parse(Read())["revision"]??0)+1;}catch{}JObject e=new JObject{{"schemaVersion",1},{"feature","video"},{"type","state"},{"revision",r},{"payload",p}};string j=e.ToString(Formatting.None);CPH.SetGlobalVar(Key,j,true);try{CPH.WebsocketBroadcastJson(j);}catch(Exception x){CPH.LogWarn("[video] Broadcast failed: "+x.Message);}return true;}
 string Read(){try{return CPH.GetGlobalVar<string>(Key,true)??"";}catch{return "";}} long Now(){return DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();}string A(string k){try{return args.ContainsKey(k)&&args[k]!=null?args[k].ToString().Trim():"";}catch{return "";}}
 bool Bool(string k,bool f){bool v;return Boolean.TryParse(A(k),out v)?v:f;}double Number(string k,double f,double min,double max){double v;if(!Double.TryParse(A(k),NumberStyles.Any,CultureInfo.InvariantCulture,out v))v=f;return Clamp(v,min,max);}double Clamp(double v,double min,double max){return Math.Max(min,Math.Min(max,v));}
 string Choice(string v,string[] a,string f){foreach(string x in a)if(String.Equals(v,x,StringComparison.OrdinalIgnoreCase))return x;return f;}string Id(string v){return Regex.Replace((v??"").Trim().ToLowerInvariant(),"[^a-z0-9_-]","");}string Limit(string v,int n){v=(v??"").Trim();return v.Length<=n?v:v.Substring(0,n);}string Colour(string v,string f){return Regex.IsMatch(v??"","^#[0-9a-fA-F]{6}$")?v:f;}bool Safe(string v){v=(v??"").Trim();return v.StartsWith("/streaming/videos/",StringComparison.OrdinalIgnoreCase)||v.StartsWith("http://127.0.0.1:7474/streaming/videos/",StringComparison.OrdinalIgnoreCase)||v.StartsWith("http://localhost:7474/streaming/videos/",StringComparison.OrdinalIgnoreCase);}string Absolute(string v){return v.StartsWith("/")?Base+v:v;}
}